\label{prop:3-1} Suppose $0<r_{1}\leq r_{2}\leq\cdots<1$, $r_{j}\to1$,
and 
\[
\sum_{j\geq1}\left(1-r^{2}_{j}\right)=\infty.
\]
For each $Q\in\mathbb{Z}_{+}$, there exist $g_{j}>0$ with $\sum_{j}g^{2}_{j}=1$
such that,
\begin{equation}
\sum_{n\geq0}\frac{g^{2}_{j}r^{2n}_{j}}{m_{n}}=Q,\quad j\geq1.\label{eq:3-1}
\end{equation}

A more recent selector theorem \cite[Corollary 4.8]{BownikSelector2026}
improves the group size requirement from $CB\varepsilon^{-4}$ to
$CB\varepsilon^{-2}$. So $Q$ may be chosen of order $\varepsilon^{-2}$.

\label{thm:4-3} Let $0<r_{j}<1$ and $r_{j}\to1$. The following
are equivalent. 
\begin{enumerate}
\item \label{enu:4-3a}There exist $\lambda_{j}\in\mathbb{C}$ with $\left|\lambda_{j}\right|=r_{j}$
and $g\in\ell^{2}$ such that the normal operator $T$ defined by
$Te_{j}=\lambda_{j}e_{j}$ has a normalized orbit 
\[
\left\{ \frac{T^{n}g}{\left\Vert T^{n}g\right\Vert }\right\} _{n\geq0}
\]
which is a frame for $\ell^{2}$.
\item \label{enu:4-3b}The series $\sum_{j\geq1}\left(1-r^{2}_{j}\right)$
diverges. 
\end{enumerate}
Moreover, assume 
\begin{equation}
\sum_{j\geq1}\left(1-r^{2}_{j}\right)=\infty.\label{eq:4-4a}
\end{equation}
Then, for every $\varepsilon\in\left(0,1\right)$, there exists $Q=Q\left(\varepsilon\right)\in\mathbb{Z}_{+}$,
for which $T$ and a unit vector $g$ can be chosen so that 
\begin{equation}
Q\left(1-\varepsilon\right)\left\Vert h\right\Vert ^{2}\leq\sum_{n\geq0}\left|\left\langle \frac{T^{n}g}{\left\Vert T^{n}g\right\Vert },h\right\rangle \right|^{2}\leq Q\left(1+\varepsilon\right)\left\Vert h\right\Vert ^{2},\quad h\in\ell^{2}.\label{eq:4-4}
\end{equation}
